/**
 * 本文件由 scripts/build.mjs 生成，请勿手工编辑。
 * 修改样式请编辑 src/client/styles/*.css，然后运行 `node scripts/build.mjs`。
 */
export const STYLES = [
  ["base", "/*\n * 界面美化 · Lumina —— 基础层：画布氛围、选区、滚动条、交互过渡。\n *\n * 规则约束（与宿主 docs/web-styling 的取向一致）：\n *   1. 只使用三类稳定选择器 —— 元素选择器、ARIA role/状态属性、\n *      宿主明确设置的 data-* 属性；\n *   2. 需要覆盖宿主令牌化属性时，用 `html body` 前缀提升特异性，\n *      不写 !important（inline 令牌本来就该由 overrideTokens 负责）；\n *   3. CSS Module 的类名形如 `{hash}_{local}`，哈希随构建变化，\n *      因此只在确有必要时用 `[class*='_local']` 这种与哈希无关的后缀匹配，\n *      匹配不到时静默降级，绝不报错。\n */\n\n/* ------------------------------------------------------------------ *\n * 1. 页面根：把主题色透出到浏览器/窗口底色，并保住 body 背景的可预测性\n * ------------------------------------------------------------------ */\n\nhtml body {\n  background-color: var(--dsw-alias-bg-base);\n}\n\n/* ------------------------------------------------------------------ *\n * 2. 氛围光\n *\n *    只挂在**侧栏列**上。这一条是踩过坑之后收紧的：\n *\n *    最初同时挂在框架（`[class*='_frame']`）上。框架本来被两列完全盖住，\n *    唯一露出来的地方是 Windows 标题栏模式下中心列左上角那个\n *    `border-radius: 16px` 的圆角 —— 而 background-image 的默认原点\n *    （background-origin: padding-box）恰好就在内容区左上角。于是那个圆角\n *    里露出的是光斑**最亮的那一点**，被圆角切成一块带硬边的蓝色楔形，\n *    在浅色下非常显眼。\n *\n *    框架不需要氛围光：它可见的部分只有标题栏拖拽带（被 `:before` 盖住）\n *    和上述圆角露出的区域，而那两处应当是与侧栏连续的纯色。\n * ------------------------------------------------------------------ */\n\nhtml[data-dshb-ambient='on'] body [class*='_sidebarCol'] {\n  background-image: radial-gradient(\n      120% 55% at 0% 0%,\n      var(--dshb-ambient-a),\n      var(--dshb-ambient-a-fade) 70%\n    ),\n    radial-gradient(\n      120% 50% at 100% 100%,\n      var(--dshb-ambient-b),\n      var(--dshb-ambient-b-fade) 72%\n    );\n  /* radial-gradient 默认就铺满整个盒子，no-repeat 对它是空操作，\n     写出来只会让下一个人以为这里有平铺行为。 */\n}\n\n/* ------------------------------------------------------------------ *\n * 3. 文本选区：官方是 40% 蓝，这里改为强调色，与品牌位保持一致\n * ------------------------------------------------------------------ */\n\nhtml body ::selection {\n  background-color: var(--dsw-alias-bg-document-selection);\n}\n\n/* ------------------------------------------------------------------ *\n * 4. 滚动条：官方 5px 无边框。这里给滑块留出 1.5px 透明边，视觉更细但\n *    命中区域不变宽（宽度由 --dsh-scrollbar-width 决定，保持 6px）。\n *    WebKit 路径走伪元素；Firefox 路径由 scrollbar.css 的宽细标准接管。\n * ------------------------------------------------------------------ */\n\nhtml body {\n  --dsh-scrollbar-width: 6px;\n  --dsh-scrollbar-thumb-border: 1.5px;\n  --dsh-scrollbar-track-margin: 4px;\n}\n\n/* ------------------------------------------------------------------ *\n * 5. 交互过渡\n *    只过渡「颜色类」属性 —— 布局属性加过渡会造成拖拽/折叠时的粘滞感。\n *    尊重 prefers-reduced-motion：命中时整段失效。\n * ------------------------------------------------------------------ */\n\n@media (prefers-reduced-motion: no-preference) {\n  html[data-dshb-motion='on']\n    body\n    :is(\n      button,\n      a,\n      summary,\n      input,\n      textarea,\n      select,\n      [role='button'],\n      [role='menuitem'],\n      [role='menuitemcheckbox'],\n      [role='menuitemradio'],\n      [role='option'],\n      [role='tab'],\n      [role='switch'],\n      [role='checkbox'],\n      [role='radio']\n    ) {\n    transition: background-color var(--ds-transition-duration-fast)\n        var(--ds-ease-in-out),\n      border-color var(--ds-transition-duration-fast) var(--ds-ease-in-out),\n      color var(--ds-transition-duration-fast) var(--ds-ease-in-out),\n      box-shadow var(--ds-transition-duration-fast) var(--ds-ease-in-out),\n      opacity var(--ds-transition-duration-fast) var(--ds-ease-in-out);\n  }\n\n  /* 浮层与卡片入场时给一点高度变化，避免菜单「凭空出现」 */\n  html[data-dshb-motion='on'] body [data-menu-material],\n  html[data-dshb-motion='on'] body [role='dialog'],\n  html[data-dshb-motion='on'] body [role='menu'],\n  html[data-dshb-motion='on'] body [role='listbox'] {\n    transition: opacity var(--ds-transition-duration) var(--ds-ease-in-out),\n      transform var(--ds-transition-duration) var(--ds-ease-in-out),\n      box-shadow var(--ds-transition-duration) var(--ds-ease-in-out);\n  }\n}\n\n/* ------------------------------------------------------------------ *\n * 6. 焦点环：颜色已由 --dsw-focus-ring-color 令牌接管（随强调色走），\n *    这里只补一点外发光，让键盘焦点在复杂卡片上更容易被找到。\n * ------------------------------------------------------------------ */\n\nhtml body :focus-visible {\n  outline-offset: 2px;\n}\n\n/* ------------------------------------------------------------------ *\n * 7. 内容区圆角\n *\n *    Windows 标题栏模式下，宿主把中心列左上角切成\n *    `border-radius: var(--dsh-windows-content-radius) 0 0 0; corner-shape: round`，\n *    那个圆角露出的正是框架底色 —— 也就是侧栏填充色。它是整块内容区视觉上\n *    最靠外的一个圆角，必须与相邻表面（卡片、面板）用同一支笔。\n *\n *    宿主把该令牌声明在 frame 元素**自身**上（`[data-windows-titlebar]\n *    .xxx_frame`，特异性 0,0,2,0），body 上的行内值只够被继承，够不着它。\n *    因此这里用 `html body [class*='_frame']`（0,0,2,1）覆盖，取值来自插件\n *    原语 `--dshb-content-radius`，与圆角档位联动。\n *\n *    宿主同时写了 `corner-shape: round`：这个角是**正圆**，不是全局的方圆形。\n *    保持不动 —— 它是内容区最外沿的轮廓，跟随全局方圆形会让四个角与窗口\n *    自身的圆角对不上。\n * ------------------------------------------------------------------ */\n\nhtml body [class*='_frame'] {\n  --dsh-windows-content-radius: var(--dshb-content-radius);\n}\n"],
  ["elevation", "/*\n * 界面美化 · Lumina —— 高度（elevation）令牌重组层。\n *\n * ## 为什么这一层必须存在\n * 宿主 gradient-shadow-text.css 把 `--dsw-elevation-*` 声明在 `body, body *` 上 ——\n * 也就是**每一个元素都自带一份声明**。插件通过 ctx.theme.overrideTokens 拿到的\n * 是 body 上的行内样式，行内值只能被继承；元素自带的声明优先于继承，所以行内\n * 覆盖对这一族令牌完全无效（这是宿主令牌体系里唯一一处这样的例外）。\n *\n * ## 怎么解\n * 插件改为交出「原语」：--dshb-elev-stroke-color / --dshb-elev-panel 等，\n * 它们没有第二个声明点，行内值可正常继承到所有后代；再由本表把这些原语组合成\n * 宿主令牌。选择器写成 `html body` / `html body *`，特异性严格高于宿主的\n * `body` / `body *`，因此不依赖样式表顺序、也不需要 !important。\n */\n\nhtml body,\nhtml body * {\n  --dsw-elevation-stroke: 0 0 0 0.5px var(--dshb-elev-stroke-color);\n  --dsw-elevation-panel: var(--dsw-elevation-stroke), var(--dshb-elev-panel);\n  --dsw-elevation-prominent: var(--dsw-elevation-stroke),\n    var(--dshb-elev-prominent);\n  --dsw-elevation-soft: var(--dsw-elevation-stroke), var(--dshb-elev-soft);\n}\n\n/*\n * 宿主在深色模式下给菜单材质换了一根更亮的描边色。官方值来自 border-l3，\n * 这里改用本预设的 stroke 原语，让菜单描边与其余浮层保持同一支笔。\n * 选择器特异性 (0,0,2,2) 高于宿主的 (0,0,2,1)。\n */\nhtml body[data-ds-dark-theme] [data-menu-material],\nhtml body [data-menu-material] {\n  --dsw-elevation-stroke-color: var(--dshb-elev-stroke-color);\n}\n"],
  ["typography", "/*\n * 界面美化 · Lumina —— 内容排版精修层（可用 data-dshb-typography 整体关闭）。\n *\n * 这一层处理令牌表达不了的东西：字形平滑、等宽数字、代码块与引用块的细节。\n * 全部使用元素选择器 —— 它们由宿主 Markdown 渲染器产出，与 CSS Module 哈希无关，\n * 因此跨版本稳定；代价是无法区分「会话里的表格」与「插件面板里的表格」，\n * 这对视觉一致性而言反而是好事。\n *\n * 打开/关闭由 <html data-dshb-typography=\"on|off\"> 控制。\n */\n\n/* ------------------------------------------------------------------ *\n * 1. 字形渲染\n * ------------------------------------------------------------------ */\n\nhtml[data-dshb-typography='on'] body {\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  text-rendering: optimizeLegibility;\n}\n\n/* 中文正文在 system-ui 下字距偏挤；0.01em 是几乎察觉不到、但整页读起来更松的量 */\nhtml[data-dshb-typography='on'] body :is(p, li, dd, dt, td, th) {\n  letter-spacing: 0.01em;\n}\n\n/* 表格、代码、时间戳里的数字等宽，列才对得齐 */\nhtml[data-dshb-typography='on'] body :is(table, code, kbd, samp, pre) {\n  font-variant-numeric: tabular-nums;\n  font-feature-settings: 'tnum' 1, 'cv05' 1;\n}\n\n/* ------------------------------------------------------------------ *\n * 2. 代码\n * ------------------------------------------------------------------ */\n\n/* 行内代码：官方只给底色，这里补一根极淡描边，让它从正文里「浮」起来 */\nhtml body :not(pre) > code {\n  border: 1px solid var(--dsw-alias-border-l1);\n  border-radius: var(--dsw-radius-xs);\n  padding: 0.1em 0.34em;\n}\n\n/* 代码块：圆角 + 描边 + 顶部一道极淡高光，避免大面积实色显得扁平 */\nhtml body pre {\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: var(--dsw-radius-md);\n  box-shadow: inset 0 1px 0 0 var(--dsw-alias-border-l1);\n}\n\n/* ------------------------------------------------------------------ *\n * 3. 引用与分隔\n * ------------------------------------------------------------------ */\n\nhtml[data-dshb-typography='on'] body blockquote {\n  border-inline-start: 3px solid var(--dsw-alias-state-business-primary);\n  border-radius: 0 var(--dsw-radius-sm) var(--dsw-radius-sm) 0;\n  padding-inline-start: 0.85em;\n}\n\nhtml[data-dshb-typography='on'] body hr {\n  border: 0;\n  border-top: 1px solid var(--dsw-alias-border-l2);\n}\n\n/* ------------------------------------------------------------------ *\n * 4. 表格\n * ------------------------------------------------------------------ */\n\nhtml[data-dshb-typography='on'] body th {\n  background-color: var(--dsw-alias-markdown-code-block-banner);\n}\n\nhtml[data-dshb-typography='on'] body table {\n  border-radius: var(--dsw-radius-sm);\n  overflow: clip;\n}\n\n/* ------------------------------------------------------------------ *\n * 5. 链接与图片\n * ------------------------------------------------------------------ */\n\nhtml[data-dshb-typography='on'] body a {\n  text-underline-offset: 0.22em;\n  text-decoration-thickness: 0.06em;\n}\n\nhtml[data-dshb-typography='on'] body :is(img, video) {\n  border-radius: var(--dsw-radius-sm);\n}\n"],
  ["safety", "/*\n * 界面美化 · Lumina —— 安全修正层。\n *\n * 这一层不放任何装饰。它只修一个宿主自身的问题：**页面控件被原生窗口按钮盖住，\n * 用户点到的是「关闭程序」**。\n *\n * ## 问题\n * Windows 上宿主用 Electron 的 `titleBarOverlay` 画最小化/最大化/关闭三个按钮。\n * 它们不在 DOM 里 —— Chromium 把它们绘制在页面**之上**，占位约\n * `top: 0..40px`、`right: 0..138px`（高度来自 host preload 写入的\n * `--dsh-windows-titlebar-height: 40px`）。\n *\n * 而图片灯箱的关闭按钮是：\n *\n *   .close { position: fixed; top: 20px; right: 20px; width: 36px; height: 36px }\n *   （宿主 ui-primitives 的 ImageLightbox.module.css）\n *\n * 它整个落在那三个原生按钮的下半部分里。因为原生覆盖层在上，点击被它截走 ——\n * 用户点「图片的 ✕」，程序被关掉。这是可复现的误操作，不是观感问题。\n *\n * ## 修法\n * 把灯箱关闭按钮挪到标题栏覆盖层**下方**。位移量不写死，而是用宿主自己发布的\n * `--dsh-frame-overlay-top`：ui-layout 把它定义为\n * `calc(--dsh-frame-top-clearance + 20px)`，而全屏时宿主会把它降回 20px ——\n * 全屏下原生按钮本就不显示，关闭按钮自动回到原位，不需要插件再加一条全屏判断。\n *\n * ## 选择器\n * 用与哈希无关的后缀匹配：编译后的类名形如 `_backdrop_1hos8_1` / `_close_1hos8_29`。\n * 全应用只有一个 `_backdrop` 类（图片灯箱），因此\n * `[class*='_backdrop'] [class*='_close_']` 唯一且稳定。匹配不到时静默降级 ——\n * 宿主哪天自己修好了，这条规则自动失效，不会有副作用。\n *\n * `scripts/check.mjs` 会断言这条规则始终挂在 `[data-windows-titlebar]` 下并引用\n * 宿主变量；`scripts/audit-caption-collision.mjs` 可在宿主升级后重新全量排查。\n */\n\nhtml[data-windows-titlebar] body [class*='_backdrop'] [class*='_close_'] {\n  top: var(--dsh-frame-overlay-top, 60px);\n}\n"],
  ["panel", "/*\n * 界面美化 · Lumina —— 设置面板样式。\n *\n * 类名统一用 `dshb-` 前缀的普通全局类（不是 CSS Module）：面板组件由本插件\n * 拥有，前缀足以避免与宿主及其它插件冲突，同时也省掉一层构建期哈希。\n *\n * 全部颜色都读宿主令牌，因此面板会跟随浅色/深色与所选预设一起变。\n *\n * ## 正圆与胶囊必须写 corner-shape: round\n * 宿主的 corner-shape.css 通过 `*,:before,:after { corner-shape: superellipse(1.5) }`\n * 把**所有**圆角平滑成方圆形。这对卡片、输入框是想要的效果，但会把\n * `border-radius: 50%` 的圆和 `999px` 的胶囊压变形。宿主自己的约定是：\n * 正圆形状需在所属组件样式表里把 `corner-shape: round` 与半径声明配对。\n * 本文件里四处圆（色板、预设色点、开关轨道、开关滑块）都遵守这一约定。\n * 不支持 corner-shape 的引擎会忽略该声明，退化成普通圆弧 —— 正是想要的。\n */\n\n.dshb-root {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  color: var(--dsw-alias-label-primary);\n  font-family: var(--dsw-font-family);\n  font-size: var(--dsh-content-font-size-secondary, 13px);\n}\n\n/* ---------------------------------------------------------------- 头部 */\n\n.dshb-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.dshb-title {\n  margin: 0;\n  font-size: 16px;\n  font-weight: 600;\n  line-height: 24px;\n  color: var(--dsw-alias-label-primary);\n}\n\n.dshb-subtitle {\n  margin: 4px 0 0;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n  max-width: 46ch;\n}\n\n/* ------------------------------------------------------------ 主体容器 */\n\n.dshb-body {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  border: 1px solid var(--dsw-alias-settings-card-stroke, var(--dsw-alias-border-l4));\n  border-radius: var(--dsw-radius-md);\n  background-color: var(\n    --dsw-alias-settings-card-fill,\n    var(--dsw-alias-bg-layer-2)\n  );\n  padding: 4px 16px;\n}\n\n/* 总开关关闭时整块降饱和并禁用交互，明确表达「已停用」 */\n.dshb-body-off {\n  opacity: 0.45;\n  filter: saturate(0.4);\n  pointer-events: none;\n}\n\n/* ------------------------------------------------------------------ 行 */\n\n.dshb-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  padding: 14px 0;\n  border-bottom: 1px solid var(--dsw-alias-border-l1);\n}\n\n.dshb-row:last-child {\n  border-bottom: 0;\n}\n\n.dshb-row-text {\n  min-width: 0;\n}\n\n.dshb-row-title {\n  font-size: 13px;\n  font-weight: 500;\n  line-height: 20px;\n  color: var(--dsw-alias-label-primary);\n}\n\n.dshb-row-hint {\n  margin-top: 2px;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n}\n\n.dshb-row-control {\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n/* ------------------------------------------------------------- 预设卡片 */\n\n.dshb-group {\n  padding: 14px 0;\n  border-bottom: 1px solid var(--dsw-alias-border-l1);\n}\n\n.dshb-group-title {\n  font-size: 13px;\n  font-weight: 500;\n  line-height: 20px;\n  margin-bottom: 10px;\n}\n\n.dshb-cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(132px, 1fr));\n  gap: 10px;\n}\n\n.dshb-card {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 6px;\n  padding: 12px;\n  cursor: pointer;\n  text-align: left;\n  font: inherit;\n  color: var(--dsw-alias-label-primary);\n  background-color: var(--dsw-alias-bg-layer-1);\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: var(--dsw-radius-sm);\n}\n\n.dshb-card:hover:not(:disabled) {\n  background-color: var(--dsw-alias-interactive-bg-hover);\n}\n\n.dshb-card-active {\n  border-color: var(--dsw-alias-state-business-primary);\n  box-shadow: 0 0 0 1px var(--dsw-alias-state-business-primary) inset;\n  background-color: var(--dsw-alias-interactive-bg-hover-accent);\n}\n\n.dshb-card:disabled {\n  cursor: default;\n}\n\n.dshb-card-dots {\n  display: flex;\n  gap: 4px;\n}\n\n.dshb-card-dot {\n  width: 14px;\n  height: 14px;\n  border-radius: 50%;\n  /* 正圆：必须显式关掉宿主的 superellipse，否则会被压成方圆形 */\n  corner-shape: round;\n  box-shadow: 0 0 0 1px var(--dsw-alias-border-l4) inset;\n}\n\n.dshb-card-name {\n  font-size: 13px;\n  font-weight: 500;\n  line-height: 18px;\n}\n\n.dshb-card-tagline {\n  font-size: 11px;\n  line-height: 16px;\n  color: var(--dsw-alias-label-tertiary);\n}\n\n/* --------------------------------------------------------------- 色板 */\n\n.dshb-swatches {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  justify-content: flex-end;\n}\n\n.dshb-swatch {\n  width: 24px;\n  height: 24px;\n  padding: 0;\n  border-radius: 50%;\n  /* 正圆：同上，宿主会给所有元素套 superellipse */\n  corner-shape: round;\n  cursor: pointer;\n  border: 0;\n  /* 面板可能在深色下，样式表按当前主题挑选明/暗两支强调色 */\n  background-color: var(--dshb-swatch-light);\n  box-shadow: 0 0 0 1px var(--dsw-alias-border-l4) inset;\n}\n\nbody[data-ds-dark-theme] .dshb-swatch {\n  background-color: var(--dshb-swatch-dark);\n}\n\n.dshb-swatch-active {\n  box-shadow: 0 0 0 1px var(--dsw-alias-border-l4) inset,\n    0 0 0 3px var(--dsw-alias-bg-base),\n    0 0 0 5px var(--dsw-alias-state-business-primary);\n}\n\n.dshb-swatch:disabled {\n  cursor: default;\n}\n\n/* ----------------------------------------------------------- 分段选择器 */\n\n.dshb-segmented {\n  display: inline-flex;\n  padding: 2px;\n  gap: 2px;\n  border-radius: var(--dsw-radius-sm);\n  background-color: var(--dsw-alias-bg-layer-3);\n  border: 1px solid var(--dsw-alias-border-l2);\n}\n\n.dshb-segment {\n  padding: 4px 12px;\n  font: inherit;\n  font-size: 12px;\n  line-height: 18px;\n  cursor: pointer;\n  border: 0;\n  border-radius: calc(var(--dsw-radius-sm) - 3px);\n  background-color: transparent;\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dshb-segment:hover:not(:disabled) {\n  color: var(--dsw-alias-label-primary);\n  background-color: var(--dsw-alias-interactive-bg-hover);\n}\n\n.dshb-segment-active,\n.dshb-segment-active:hover:not(:disabled) {\n  background-color: var(--dsw-alias-bg-layer-1);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 500;\n  box-shadow: var(--dsw-elevation-stroke, 0 0 0 0.5px var(--dsw-alias-border-l4)),\n    0 1px 3px 0 rgb(0 0 0 / 8%);\n}\n\n/* --------------------------------------------------------------- 开关 */\n\n.dshb-switch {\n  position: relative;\n  width: 36px;\n  height: 20px;\n  padding: 0;\n  cursor: pointer;\n  border: 0;\n  border-radius: 999px;\n  /* 胶囊：superellipse 会让两端不再是半圆 */\n  corner-shape: round;\n  background-color: var(--dsw-alias-interactive-bg-active);\n  transition: background-color var(--ds-transition-duration-fast)\n    var(--ds-ease-in-out);\n}\n\n.dshb-switch[aria-checked='true'] {\n  background-color: var(--dsw-alias-state-business-primary);\n}\n\n.dshb-switch-thumb {\n  position: absolute;\n  top: 2px;\n  left: 2px;\n  width: 16px;\n  height: 16px;\n  border-radius: 50%;\n  /* 正圆：同上 */\n  corner-shape: round;\n  background-color: var(--dsw-alias-switch-thumb);\n  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 24%);\n  transition: transform var(--ds-transition-duration-fast) var(--ds-ease-in-out);\n}\n\n.dshb-switch[aria-checked='true'] .dshb-switch-thumb {\n  transform: translateX(16px);\n}\n\n/* --------------------------------------------------------------- 页脚 */\n\n.dshb-foot {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n}\n\n.dshb-reset {\n  flex: none;\n  padding: 5px 12px;\n  font: inherit;\n  font-size: 12px;\n  cursor: pointer;\n  color: var(--dsw-alias-label-secondary);\n  background-color: transparent;\n  border: 1px solid var(--dsw-alias-border-l3);\n  border-radius: var(--dsw-radius-sm);\n}\n\n.dshb-reset:hover {\n  color: var(--dsw-alias-label-primary);\n  background-color: var(--dsw-alias-interactive-bg-hover);\n}\n\n/* 尊重系统的减少动效偏好：本插件自己的过渡也一并停掉 */\n@media (prefers-reduced-motion: reduce) {\n  .dshb-switch,\n  .dshb-switch-thumb {\n    transition: none;\n  }\n}\n"]
]
